'use strict';

// MODULES //

var tape = require( 'tape' );
var Int8Array = require( '@stdlib/array/int8' );
var Uint8Array = require( '@stdlib/array/uint8' );
var Uint8ClampedArray = require( '@stdlib/array/uint8c' );
var Int16Array = require( '@stdlib/array/int16' );
var Uint16Array = require( '@stdlib/array/uint16' );
var Int32Array = require( '@stdlib/array/int32' );
var Uint32Array = require( '@stdlib/array/uint32' );
var Float32Array = require( '@stdlib/array/float32' );
var Float64Array = require( '@stdlib/array/float64' );
var copyWithin = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof copyWithin, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if not provided a collection', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			copyWithin( value, 0, 0 );
		};
	}
});

tape( 'the function copies elements within an array', function test( t ) {
	var expected;
	var actual;
	var arr;

	// Basic usage:
	arr = [ 1, 2, 3, 4, 5 ];
	actual = copyWithin( arr, 0, 3 );
	expected = [ 4, 5, 3, 4, 5 ];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( actual, arr, 'returns input array' );

	// With end index:
	arr = [ 1, 2, 3, 4, 5 ];
	actual = copyWithin( arr, 0, 3, 4 );
	expected = [ 4, 2, 3, 4, 5 ];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( actual, arr, 'returns input array' );

	// With negative indices:
	arr = [ 1, 2, 3, 4, 5 ];
	actual = copyWithin( arr, -2, -3, -1 );
	expected = [ 1, 2, 3, 3, 4 ];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( actual, arr, 'returns input array' );

	t.end();
});

tape( 'the function copies elements within a sparse array', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = [ 1, , 3, 4, 5 ]; // eslint-disable-line no-sparse-arrays
	actual = copyWithin( arr, 2, 0, 2 );
	expected = [ 1, , 1, , 5 ]; // eslint-disable-line no-sparse-arrays
	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( actual, arr, 'returns input array' );

	t.end();
});

tape( 'the function copies elements within an array-like object', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = {
		'0': 1,
		'1': 2,
		'2': 3,
		'3': 4,
		'4': 5,
		'length': 5
	};
	actual = copyWithin( arr, 0, 3 );
	expected = {
		'0': 4,
		'1': 5,
		'2': 3,
		'3': 4,
		'4': 5,
		'length': 5
	};
	t.deepEqual( actual, expected, 'returns expected value' );
	t.strictEqual( actual, arr, 'returns input array-like object' );

	t.end();
});

